// core.ts — voice notes: the shared core (docs/VOICE-NOTES.md §5). Pure: no DOM, no I/O.
// The desktop's crates/widgets/src/voicenote.rs is a line-for-line port; both replay testvectors/voice-notes/vectors.json
// (a byte-identical copy in both repos, generated by an independent reference: tools/voice-notes/oracle.py).
// Integer maths after one rule-defined f32 → i16 quantisation, so the two sides agree bit for bit.

/** Capture rate both sides record at (Hz). */
export const VOICE_RATE = 48000;
/** Samples per level frame: 10 ms at VOICE_RATE. */
export const VOICE_FRAME = 480;
/** Waveform points in the event (Element and others resample whatever they get). */
export const WAVEFORM_N = 100;
/** A frame peak below this never fills the waveform (near-silence stays flat). Same unit as the peaks (0..32768). */
export const WAVEFORM_FLOOR = 1024;
/** Longest note (ms); recording stops into review on its own. Matches Element's 15 minutes. */
export const VOICE_MAX_MS = 900_000;
/** "Ending soon" hint this long before the cap. */
export const VOICE_WARN_LEFT_MS = 10_000;
/** Shorter than this is discarded as a mis-tap ("Hold on — that was too short to send"). */
export const VOICE_MIN_MS = 500;
/** The event's body and text fallback. */
export const VOICE_BODY = "Voice message";

/** One sample → i16, by rule: the sample is an f32, widened to f64, all arithmetic f64: floor(x·32768 + 0.5) clamped to
 *  [-32768, 32767]; NaN → 0. */
export function quantize(x: number): number {
  const v = Math.floor(Math.fround(x) * 32768 + 0.5);
  if (v !== v) return 0;
  return v < -32768 ? -32768 : v > 32767 ? 32767 : v;
}

/** Streaming frame peaks: feed sample chunks of any size; one peak (max |i16|, 0..32768) per `frame` samples; finish()
 *  adds the partial last frame. Chunk boundaries never change the result. */
export class PeakMeter {
  readonly peaks: number[] = [];
  private cur = 0;
  private n = 0;
  samples = 0;
  readonly frame: number;
  constructor(frame: number = VOICE_FRAME) {
    this.frame = Math.max(1, frame);
  }
  push(chunk: ArrayLike<number>): void {
    for (let i = 0; i < chunk.length; i++) {
      const q = quantize(chunk[i]!);
      const a = q < 0 ? -q : q;
      if (a > this.cur) this.cur = a;
      this.n++;
      if (this.n === this.frame) {
        this.peaks.push(this.cur);
        this.cur = 0;
        this.n = 0;
      }
    }
    this.samples += chunk.length;
  }
  /** The peak of the frame being filled (the live meter), 0..32768. */
  get live(): number {
    return this.n > 0 ? this.cur : this.peaks.length ? this.peaks[this.peaks.length - 1]! : 0;
  }
  finish(): number[] {
    if (this.n > 0) {
      this.peaks.push(this.cur);
      this.cur = 0;
      this.n = 0;
    }
    return this.peaks;
  }
}

/** Integer square root (floor). Exact for every input the waveform produces (≤ 2^20). */
export function isqrt(x: number): number {
  if (x <= 0) return 0;
  let r = Math.floor(Math.sqrt(x));
  while (r * r > x) r--;
  while ((r + 1) * (r + 1) <= x) r++;
  return r;
}

/** Frame peaks → the event waveform: min(n, frames) points in 0..1024. Bucket i = frames [⌊i·F/N⌋, ⌊(i+1)·F/N⌋), its max
 *  peak p, scaled against the loudest frame (at least WAVEFORM_FLOOR): ⌊√(⌊p·2^20 / denom⌋)⌋ — a square-root curve so
 *  speech reads as speech, not as a few spikes. */
export function waveform(peaks: readonly number[], n: number = WAVEFORM_N): number[] {
  const F = peaks.length;
  if (F === 0 || n <= 0) return [];
  const N = Math.min(n, F);
  let max = 0;
  for (const p of peaks) if (p > max) max = p;
  const denom = Math.max(max, WAVEFORM_FLOOR);
  const out: number[] = [];
  for (let i = 0; i < N; i++) {
    const lo = Math.floor((i * F) / N);
    const hi = Math.floor(((i + 1) * F) / N);
    let p = 0;
    for (let j = lo; j < hi; j++) if (peaks[j]! > p) p = peaks[j]!;
    out.push(Math.min(1024, isqrt(Math.floor((p * 1048576) / denom))));
  }
  return out;
}

/** Samples at `rate` → whole milliseconds, half up. */
export function durationMs(samples: number, rate: number = VOICE_RATE): number {
  return Math.floor((samples * 1000 + Math.floor(rate / 2)) / rate);
}

/** The base type only, lower case ("audio/webm;codecs=opus" → "audio/webm"). */
export function baseMime(mime: string): string {
  return mime.split(";")[0]!.trim().toLowerCase();
}

/** "Voice message.<ext>" for the container we send. */
export function voiceFileName(mime: string): string {
  const ext: Record<string, string> = { "audio/ogg": "ogg", "audio/webm": "webm", "audio/mp4": "m4a", "audio/mpeg": "mp3" };
  return `${VOICE_BODY}.${ext[baseMime(mime)] ?? "ogg"}`;
}

export interface EncryptedFileRef {
  url: string;
  [k: string]: unknown;
}

export interface VoiceContentIn {
  /** Unencrypted room: the upload's mxc. */
  mxc?: string;
  /** Encrypted room: the EncryptedFile (with its url). */
  file?: EncryptedFileRef;
  mimetype: string;
  size: number;
  duration: number;
  waveform: number[];
}

/** The m.room.message content of a voice note — Element's createVoiceMessageContent shape (MSC3245 voice + MSC1767
 *  audio/file/text), with `url`/`file` per room and the base mimetype. */
export function voiceContent(i: VoiceContentIn): Record<string, unknown> {
  const mime = baseMime(i.mimetype);
  const f: Record<string, unknown> = { name: voiceFileName(mime), mimetype: mime, size: i.size };
  const c: Record<string, unknown> = {
    msgtype: "m.audio",
    body: VOICE_BODY,
    info: { mimetype: mime, size: i.size, duration: i.duration },
    "org.matrix.msc1767.text": VOICE_BODY,
    "org.matrix.msc1767.file": f,
    "org.matrix.msc1767.audio": { duration: i.duration, waveform: [...i.waveform] },
    "org.matrix.msc3245.voice": {},
  };
  if (i.file) {
    c.file = i.file;
    f.file = i.file;
  } else {
    c.url = i.mxc;
    f.url = i.mxc;
  }
  return c;
}

/** Is this content a voice note (MSC3245)? */
export function isVoiceNote(c: { msgtype?: unknown; [k: string]: unknown } | null | undefined): boolean {
  return !!c && c.msgtype === "m.audio" && c["org.matrix.msc3245.voice"] !== undefined;
}

/** Recorded waveform of a received note (0..1024 ints) or null when absent/malformed. */
export function noteWaveform(c: Record<string, unknown> | null | undefined): number[] | null {
  const a = c?.["org.matrix.msc1767.audio"] as { waveform?: unknown } | undefined;
  const w = a?.waveform;
  if (!Array.isArray(w) || w.length === 0) return null;
  const out: number[] = [];
  for (const v of w) {
    if (typeof v !== "number" || !Number.isFinite(v)) return null;
    out.push(Math.max(0, Math.min(1024, Math.round(v))));
  }
  return out;
}

/** mm:ss of a duration (the timer and the review chip). */
export function clock(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}
